const Autobase = require('autobase')
const b4a = require('b4a')
const { Readable } = require('streamx')

module.exports = { create_auditcore }

function create_auditcore (options) {
  const { store, bootstrap, opts = {} } = options
  const emitter = make_emitter()
  const state = { store, bootstrap, opts, base: null }

  state.base = new Autobase(store, bootstrap, {
    valueEncoding: 'json',
    open: handle_autobase_open,
    apply: handle_autobase_apply,
    ackInterval: opts.ack_interval || 1000,
    ackThreshold: opts.ack_threshold || 1,
    fastForward: false
  })

  state.base.on('update', handle_base_update)

  function handle_base_update () {
    emitter.emit('update')
  }

  const api = {
    get base () { return state.base },
    get key () { return state.base ? state.base.key : null },
    get writable () { return state.base ? state.base.writable : false },
    get length () { return state.base?.view ? state.base.view.log.length : 0 },
    on,
    off,
    ready,
    close,
    append,
    get,
    read,
    get_by_type,
    get_by_device,
    create_read_stream,
    add_writer,
    remove_writer,
    update,
    replicate
  }

  return api

  /***************************************
INTERNAL FUNCTIONS
***************************************/
  function on (event, listener) {
    emitter.on(event, listener)
  }

  function off (event, listener) {
    emitter.off(event, listener)
  }

  async function ready () {
    await state.base.ready()
    await state.base.update()
  }

  async function close () {
    if (state.base) await state.base.close()
  }

  // entries use our message format { head, refs, type, data, meta }. the caller only gives type and data,
  // meta.time is when this device appended it, head is set in apply from the writer that really wrote it
  async function append (entry) {
    if (!entry.type) throw new Error('Entry must have a type')
    await state.base.append({ type: entry.type, data: entry.data || {}, meta: { time: Date.now() } })
    await state.base.update()
    return api.length - 1
  }

  async function get (seq) {
    if (seq < 0 || seq >= api.length) return null
    return state.base.view.log.get(seq)
  }

  async function read (start = 0, end) {
    const stop = end !== undefined ? Math.min(end, api.length) : api.length
    const entries = []
    for (let seq = start; seq < stop; seq++) entries.push(await state.base.view.log.get(seq))
    return entries
  }

  async function get_by_type (type) {
    return (await read()).filter(function (e) {
      return e.type === type
    })
  }

  async function get_by_device (device_id) {
    return (await read()).filter(function (e) {
      return e.head[0] === device_id
    })
  }

  function create_read_stream (opts = {}) {
    const log = state.base.view.log
    let index = opts.start || 0
    const end = opts.end !== undefined ? Math.min(opts.end, log.length) : log.length
    return new Readable({ read: read_next })
    function read_next (cb) {
      if (index >= end) {
        this.push(null)
        return cb(null)
      }
      log.get(index++).then(entry => { this.push(entry); cb(null) }, cb)
    }
  }

  async function add_writer (key, is_indexer = true) {
    const key_str = typeof key === 'string' ? key : key.toString('hex')
    await state.base.append({ type: 'add_writer', data: { key: key_str, is_indexer } })
    await state.base.update()
  }

  async function remove_writer (key) {
    const key_str = typeof key === 'string' ? key : key.toString('hex')
    await state.base.append({ type: 'remove_writer', data: { key: key_str } })
    await state.base.update()
  }

  async function update () {
    return state.base.update()
  }

  function replicate (stream_or_initiator, opts = {}) {
    return state.store.replicate(stream_or_initiator, opts)
  }
}

/***************************************
GENERAL HELPER FUNCTIONS
***************************************/

/***************************************
HANDLE AUTOBASE OPEN
***************************************/
// the log is an autobase view from the store autobase gives us, so when autobase reorders it can undo entries too
function handle_autobase_open (store) {
  const log = store.get({ name: 'log', valueEncoding: 'json' })
  return { log }
}

/***************************************
HANDLE AUTOBASE APPLY
***************************************/
async function handle_autobase_apply (nodes, view, base) {
  for (const node of nodes) {
    if (node.value === null) continue
    const { type, data } = node.value
    if (type === 'add_writer') {
      await base.addWriter(b4a.from(data.key, 'hex'), { indexer: data.is_indexer })
    } else if (type === 'remove_writer') {
      // autobase throws on removing the last indexer, and since this entry is in the log that would break it on every device
      if (base.removeable(b4a.from(data.key, 'hex'))) await base.removeWriter(b4a.from(data.key, 'hex'))
    } else {
      // head[0] always comes from the writer that appended it, so no device can write in another devices name
      const head = [b4a.toString(node.from.key, 'hex')]
      const time = await next_time(view.log, node.value.meta?.time)
      await view.log.append({ head, refs: {}, type, data, meta: { time } })
    }
  }
}

// the time comes from the device that wrote the entry, apply only makes sure it never goes back. a time
// earlier than (or the same as) the entry before it becomes that time + 1, so every device builds the same log
async function next_time (log, time) {
  if (log.length === 0) return Number.isFinite(time) ? time : 0
  const previous = (await log.get(log.length - 1)).meta.time
  return Number.isFinite(time) && time > previous ? time : previous + 1
}

/***************************************
MAKE EMITTER
***************************************/
function make_emitter (state = {}) {
  return { on, off, emit }
  function on (type, callback) { (state[type] = state[type] || []).push(callback) }
  function off (type, callback) { (state[type] = state[type] || [])[state[type].indexOf(callback)] = undefined }
  function emit (type, data) {
    function handle_callback (f) {
      return f && f(data)
    }
    return (state[type] = state[type] || []).map(handle_callback)
  }
}
